 async function deletePollingStation(st:any){
  if(!confirm("Delete polling station '"+st.name+"'? A station with block allocations or duty assignments cannot be deleted."))return;
  setBusy(true);try{const [a,d]=await Promise.all([supabase.from("block_station_allocations").select("id",{count:"exact",head:true}).eq("district_id",districtId).eq("station_id",st.id),supabase.from("staff_assignments").select("id",{count:"exact",head:true}).eq("district_id",districtId).eq("station_id",st.id)]);if(a.error||d.error)throw a.error||d.error;if((a.count||0)+(d.count||0)>0)throw new Error("This station still has block allocations or duty assignments. Move its blocks and resolve assignments first.");const {data:deleted,error}=await supabase.from("polling_stations").delete().eq("id",st.id).eq("district_id",districtId).select("id");if(error)throw error;if(!deleted?.length)throw new Error("No polling station was deleted; it may already be removed or access was denied.");const numbering=await supabase.rpc("refresh_polling_station_numbers",{p_district_id:districtId});if(numbering.error)throw numbering.error;await loadDistrictData();setNotice("Polling station deleted and station numbering refreshed.");}catch(e){setNotice("Station deletion blocked: "+(e instanceof Error?e.message:String(e)));}finally{setBusy(false);}
 }
 async function moveBlockAllocation(a:any,targetId:string){
  if(!targetId||targetId===a.station_id)return;const target=stations.find(x=>x.id===targetId);if(!target)return;
  if(!confirm("Move this "+(a.gender_group||"Combined")+" block allocation to "+target.name+"? Database rules will reject gender conflicts."))return;
  setBusy(true);try{const {data:updated,error}=await supabase.from("block_station_allocations").update({station_id:targetId}).eq("id",a.id).eq("district_id",districtId).select("id").maybeSingle();if(error)throw error;if(!updated?.id)throw new Error("No allocation was moved; refresh the page and try again.");await loadDistrictData();setNotice("Block allocation moved; district summaries refreshed.");}catch(e){setNotice("Block move rejected: "+(e instanceof Error?e.message:String(e)));}finally{setBusy(false);}
 }
