   const q=await supabase.from("master_trainers").update({is_placeholder:nextPlaceholder,availability_status:nextStatus,source_data:{...(trainer.source_data||{}),"Verification Status":nextPlaceholder?"Unverified":"Verified","Availability Status":nextStatus}}).eq("id",trainer.id).eq("district_id",districtId);
   if(q.error)throw q.error;
   await loadDistrictData();
   const refreshed=await supabase.from("master_trainers").select("*").eq("district_id",districtId);
   if(!refreshed.error)setUploadRecords(refreshed.data||[]);
   setNotice(action==="verify"?"Master trainer verified and enabled.":action==="disable"?"Master trainer disabled and excluded from future batches.":"Master trainer enabled.");
